import type { TrackedNovel } from '@/types';
import { formatFromNow } from '@/utils/time';
import { stringifyError } from '@/utils/errors';
import {
  CheckCircleOutlined,
  ClockCircleOutlined,
  CloseCircleOutlined,
  DeleteOutlined,
  ExclamationCircleOutlined,
  PlayCircleOutlined,
  PauseCircleOutlined,
  ReloadOutlined,
  SyncOutlined,
} from '@ant-design/icons';
import {
  Button,
  Card,
  Flex,
  Grid,
  message,
  Popconfirm,
  Space,
  Tag,
  Tooltip,
  Typography,
} from 'antd';
import axios from 'axios';
import { useState } from 'react';

export const TrackedNovelCard: React.FC<{
  item: TrackedNovel;
  onRefresh: () => void;
}> = ({ item, onRefresh }) => {
  const { lg } = Grid.useBreakpoint();
  const [checking, setChecking] = useState(false);

  const handleForceCheck = async () => {
    setChecking(true);
    try {
      await axios.post(`/api/watcher/${item.id}/check`);
      message.success('Check complete');
      onRefresh();
    } catch (err: any) {
      message.error(stringifyError(err));
    } finally {
      setChecking(false);
    }
  };

  const handleToggleActive = async () => {
    try {
      await axios.patch(`/api/watcher/${item.id}`, {
        is_active: !item.is_active,
      });
      message.success(item.is_active ? 'Paused' : 'Resumed');
      onRefresh();
    } catch (err: any) {
      message.error(stringifyError(err));
    }
  };

  const handleDelete = async () => {
    try {
      await axios.delete(`/api/watcher/${item.id}`);
      message.success('Removed');
      onRefresh();
    } catch (err: any) {
      message.error(stringifyError(err));
    }
  };

  const statusColor = item.last_error
    ? '#ff4d4f'
    : item.is_active
      ? '#52c41a'
      : '#d9d9d9';

  return (
    <Card
      style={{
        marginBottom: 8,
        borderRadius: 8,
        overflow: 'hidden',
        borderLeft: `4px solid ${statusColor}`,
      }}
      styles={{
        body: {
          padding: lg ? '12px 20px' : '10px 15px',
        },
      }}
    >
      <Flex justify="space-between" align="center" wrap gap="small">
        <Typography.Title
          level={4}
          ellipsis
          style={{ flex: 1, margin: 0 }}
        >
          {item.title || item.novel_url}
        </Typography.Title>
        <Space size="small">
          {item.is_active ? (
            <Tag icon={<CheckCircleOutlined />} color="success">
              Active
            </Tag>
          ) : (
            <Tag icon={<PauseCircleOutlined />} color="default">
              Paused
            </Tag>
          )}
          {item.is_complete && (
            <Tag icon={<CheckCircleOutlined />} color="blue">
              Complete
            </Tag>
          )}
          <Tag>{item.output_format.toUpperCase()}</Tag>
          {item.auto_download && <Tag color="cyan">Auto-DL</Tag>}
        </Space>
      </Flex>

      <Typography.Text type="secondary" style={{ fontSize: 12 }}>
        {item.domain} &middot; Every {item.check_interval_minutes} min
        &middot; {item.last_known_chapters} chapters
      </Typography.Text>

      {item.last_error && (
        <div style={{ marginTop: 4 }}>
          <Tooltip title={item.last_error}>
            <Tag icon={<ExclamationCircleOutlined />} color="error">
              Error: {item.last_error.slice(0, 60)}
              {item.last_error.length > 60 ? '...' : ''}
            </Tag>
          </Tooltip>
        </div>
      )}

      <Flex
        justify="space-between"
        align="center"
        style={{ marginTop: 8 }}
        wrap
        gap="small"
      >
        <Space size={0} split={<span style={{ color: '#666', margin: '0 6px' }}>&middot;</span>}>
          {item.last_checked_at && (
            <Typography.Text type="secondary" style={{ fontSize: 12 }}>
              <ClockCircleOutlined /> Checked {formatFromNow(item.last_checked_at)}
            </Typography.Text>
          )}
          <Typography.Text type="secondary" style={{ fontSize: 12 }}>
            <SyncOutlined /> Added {formatFromNow(item.created_at)}
          </Typography.Text>
        </Space>

        <Space size="small">
          <Tooltip title="Check now">
            <Button
              size="small"
              icon={<ReloadOutlined spin={checking} />}
              onClick={handleForceCheck}
              loading={checking}
            />
          </Tooltip>
          <Tooltip title={item.is_active ? 'Pause' : 'Resume'}>
            <Button
              size="small"
              icon={
                item.is_active ? (
                  <PauseCircleOutlined />
                ) : (
                  <PlayCircleOutlined />
                )
              }
              onClick={handleToggleActive}
            />
          </Tooltip>
          <Popconfirm
            title="Stop tracking this novel?"
            onConfirm={handleDelete}
            okText="Yes"
            cancelText="No"
          >
            <Tooltip title="Remove">
              <Button
                size="small"
                danger
                icon={<DeleteOutlined />}
              />
            </Tooltip>
          </Popconfirm>
        </Space>
      </Flex>
    </Card>
  );
};
