import { ErrorState } from '@/components/Loading/ErrorState';
import { LoadingState } from '@/components/Loading/LoadingState';
import { EyeOutlined } from '@ant-design/icons';
import { Divider, Empty, Flex, Pagination, Select, Typography } from 'antd';
import { TrackedNovelCard } from './TrackedNovelCard';
import { useTrackedNovels } from './hooks';

export const TrackedNovelsPage: React.FC = () => {
  const {
    items,
    loading,
    error,
    total,
    currentPage,
    perPage,
    isActive,
    refresh,
    updateParams,
  } = useTrackedNovels();

  if (loading) {
    return <LoadingState />;
  }

  if (error) {
    return (
      <ErrorState
        error={error}
        title="Failed to load tracked novels"
        onRetry={refresh}
      />
    );
  }

  return (
    <>
      <Flex justify="space-between" align="center">
        <Typography.Title level={2}>
          <EyeOutlined style={{ color: '#0ca3f2' }} /> Tracked Novels
        </Typography.Title>
      </Flex>

      <Divider size="small" />

      <Flex align="center" gap={7} wrap>
        <Select
          placeholder="Filter by status"
          allowClear
          size="large"
          style={{ width: 180 }}
          value={isActive}
          onChange={(value) => updateParams({ is_active: value, page: 1 })}
          options={[
            { value: true, label: 'Active' },
            { value: false, label: 'Paused' },
          ]}
        />
      </Flex>

      <Divider size="small" />

      {items.map((item) => (
        <TrackedNovelCard key={item.id} item={item} onRefresh={refresh} />
      ))}

      {!items.length && (
        <Empty
          image={Empty.PRESENTED_IMAGE_SIMPLE}
          description="No tracked novels yet"
        />
      )}

      <Pagination
        current={currentPage}
        total={total}
        pageSize={perPage}
        showSizeChanger={false}
        onChange={(page) => updateParams({ page })}
        style={{ textAlign: 'center', marginTop: 32 }}
        hideOnSinglePage
      />
    </>
  );
};

export default TrackedNovelsPage;
